INSERT INTO tickets (id, type, parent_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('T-53', 'task', NULL, 'Don''t narrate changelog-dirty after ticket mutations', 'A `pql ticket` change (create / status transition) leaves `.pql/changelog/` dirty; the auto-commit hook persists it on the next `git commit`. This is known and expected behavior — the pre-commit hook stages `.pql/changelog/` so it lands in the same commit as the change that produced it.

Don''t narrate "the ticket won''t persist until committed" on every ticket edit. Either quietly fold the bookkeeping into a commit or trust the normal commit flow.', 'backlog', 'medium', NULL, NULL, NULL, '2026-06-06 08:48:11', '2026-06-06 08:48:11', NULL, '31c949c539ed381225e4c87dc5ec9bf1', 1) ON CONFLICT(id) DO UPDATE SET type=excluded.type, parent_id=excluded.parent_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at > tickets.updated_at OR (excluded.updated_at = tickets.updated_at AND excluded.hash > tickets.hash);
